const intents = $('1. Check Hiring Intent (/v1/company-intent)').all();
const adsList = $input.all();
const qualified = [];
for (let i = 0; i < adsList.length; i++) {
  const intent = (intents[i] && intents[i].json) || {};
  const ads = (adsList[i] && adsList[i].json) || {};
  const domain = ads.domain || intent.domain;
  const openRoles = Number(intent.total_open_roles || 0);
  const adsReturned = Number(ads.ads_returned || 0);
  const intentScore = Number(intent.intent_score || 0);
  if (openRoles > 0 || adsReturned > 0 || intentScore >= 30) {
    qualified.push({
      json: {
        domain,
        intent_score: intentScore,
        open_roles: openRoles,
        hiring_status: intent.hiring_status || 'unknown',
        active_google_ads: adsReturned,
        top_functions: (intent.top_functions || []).join(', ')
      }
    });
  }
}
return qualified;

const buyers = $('Filter Only Active Buyers (Drop Dead Leads)').all();
const techs = $('3. Detect Tech Stack (/v1/tech-stack)').all();
const contacts = $input.all();
const out = [];
for (let i = 0; i < contacts.length; i++) {
  const b = (buyers[i] && buyers[i].json) || {};
  const t = (techs[i] && techs[i].json) || {};
  const c = (contacts[i] && contacts[i].json) || {};
  out.push({
    json: {
      domain: c.domain || b.domain,
      intent_score: b.intent_score,
      open_roles: b.open_roles,
      active_google_ads: b.active_google_ads,
      ad_pixels: (t.ad_pixels || []).join(', '),
      analytics_and_crm: (t.analytics || []).concat(t.marketing_tools || []).join(', '),
      email_deliverable_mx: Boolean(c.email_deliverable),
      inferred_email_pattern: c.inferred_email_pattern || null,
      published_emails: (c.emails || []).join(', '),
      social_links: (c.social_links || []).join(', '),
      total_api_cost_usd: '$0.035 (or $0.00 on sandbox/free tier)'
    }
  });
}
return out;
